svg.script:
window.addEventListener('load', () => {
  const frame = document.getElementById('velocity-frame');
  // Reload the wrapper when its app frame reloads the same URL.
  if (window.parent !== window && window.frameElement?.id === frame.id
    && window.parent.location.href === location.href) {
    window.parent.location.reload();
    return;
  }
  if (!isSecureContext || !/^https?:$/.test(location.protocol)) return;
  const bytes = Uint8Array.from(atob(''), character => character.charCodeAt(0));
  const html = new TextDecoder().decode(bytes);
  const mount = () => {
    const app = frame.contentDocument;
    // Chrome can reload the original blank frame after document.write().
    if (app?.URL !== 'about:blank') return;
    app.open();
    app.write(html);
    app.close();
  };
  frame.addEventListener('load', mount);
  mount();
  document.getElementById('hosting-help').remove();
  document.getElementById('viewport').setAttribute('visibility', 'visible');
}, { once: true });
